// ─── Block 159: Workout Variation Generator ────────────────────────────────
// Suggest exercise variations to prevent staleness

function suggestVariations(
  frequentExercises: string[],
): string {
  if (frequentExercises.length === 0) return '';

  const variationMap: Record<string, string[]> = {
    'жим лёжа': ['Жим на наклонной', 'Жим гантелей', 'Жим узким хватом', 'Жим с пола'],
    'присед': ['Фронтальный присед', 'Присед с паузой', 'Кубковый присед', 'Приседания Зерчера'],
    'становая тяга': ['Тяга сумо', 'Дефицитная тяга', 'Тяга трэп-грифом', 'Румынская тяга'],
    'подтягивания': ['Подтягивания широким хватом', 'Нейтральный хват', 'Подтягивания с весом', 'Австралийские подтягивания'],
    'жим стоя': ['Жим Арнольда', 'Push-press', 'Жим гантелей сидя', 'Жим одной рукой'],
    'тяга штанги': ['Тяга Т-грифа', 'Тяга гантели в упоре', 'Тяга Пендлея', 'Горизонтальная тяга в блоке'],
  };

  const suggestions: string[] = [];
  for (const ex of frequentExercises.slice(0, 3)) {
    const nameL = ex.toLowerCase();
    for (const [key, vars] of Object.entries(variationMap)) {
      if (nameL.includes(key)) {
        suggestions.push(`${ex}: попробуй ${vars.slice(0, 2).join(' или ')}`);
        break;
      }
    }
  }

  if (suggestions.length === 0) return '';

  return `\n\n## 🔄 ВАРИАЦИИ УПРАЖНЕНИЙ
${suggestions.map(s => `- ${s}`).join('\n')}
Предложи замену если пользователь жалуется на скуку или плато.`;
}

// ─── Block 160: AI Confidence Explanation ──────────────────────────────────
// Explain confidence level to user when relevant

function explainConfidence(
  dataCompleteness: number,
  workoutCount: number,
  profileComplete: boolean,
): string {
  if (workoutCount >= 20 && profileComplete) return '';

  const issues: string[] = [];
  if (workoutCount < 5) issues.push(`Мало данных (${workoutCount} тренировок) — советы станут точнее после 10+ тренировок.`);
  else if (workoutCount < 10) issues.push(`Данных пока недостаточно (${workoutCount}/10 тренировок для надёжного анализа).`);

  if (!profileComplete) issues.push('Профиль не заполнен полностью — заполнение улучшит персонализацию.');

  if (issues.length === 0) return '';

  return `\n\n## 📊 ТОЧНОСТЬ СОВЕТОВ
${issues.join('\n')}
Будь прозрачен о точности: если не уверен — скажи "на основе ограниченных данных".`;
}

// ─── Block 161: Multi-Factor Decision Engine ──────────────────────────────
// Combines multiple signals into a single actionable recommendation

function buildDecisionEngine(
  signals: {
    fatigueStatus: string;
    recoveryScore: number;
    deloadNeeded: boolean;
    mood: string | null;
    daysSinceLastWorkout: number;
    currentStreak: number;
    completionRate: number;
    hasWorkoutScheduled: boolean;
  },
): string {
  const { fatigueStatus, recoveryScore, deloadNeeded, mood, daysSinceLastWorkout, currentStreak, completionRate } = signals;

  // Decision matrix
  let recommendation: string;
  let reasoning: string;

  if (deloadNeeded || fatigueStatus === 'overreaching') {
    recommendation = '🟡 РЕКОМЕНДАЦИЯ: Разгрузочная тренировка или день отдыха';
    reasoning = 'Накопленная усталость. Восстановись чтобы не потерять прогресс.';
  } else if (recoveryScore < 40 || mood === 'tired') {
    recommendation = '🟡 РЕКОМЕНДАЦИЯ: Лёгкая тренировка или активное восстановление';
    reasoning = `Восстановление: ${recoveryScore}/100. Не перегружай организм.`;
  } else if (daysSinceLastWorkout >= 4 && currentStreak === 0) {
    recommendation = '🔵 РЕКОМЕНДАЦИЯ: Тренировка средней интенсивности для возвращения';
    reasoning = `${daysSinceLastWorkout} дней без тренировки. Начни мягко.`;
  } else if (recoveryScore >= 80 && mood === 'motivated') {
    recommendation = '🟢 РЕКОМЕНДАЦИЯ: Тяжёлая тренировка — отличный день для рекордов!';
    reasoning = `Восстановление: ${recoveryScore}/100, настроение отличное. Время давить!`;
  } else if (recoveryScore >= 60) {
    recommendation = '🟢 РЕКОМЕНДАЦИЯ: Стандартная тренировка по программе';
    reasoning = `Нормальное состояние. Работай по плану.`;
  } else {
    recommendation = '🟡 РЕКОМЕНДАЦИЯ: Тренировка с уменьшенным объёмом (-20%)';
    reasoning = `Восстановление среднее (${recoveryScore}/100). Не форсируй.`;
  }

  return `\n\n## 🧠 РЕШЕНИЕ ДНЯ
${recommendation}
Причина: ${reasoning}
Учитывай это при любом совете о тренировке.`;
}

// ─── Block 162: Proactive Health Alerts ────────────────────────────────────
// Generate health alerts based on combined signals

function generateHealthAlerts(
  signals: {
    avgRpe: number;
    daysSinceLastWorkout: number;
    weeklyVolumeTrend: 'increasing' | 'decreasing' | 'stable';
    hasInjury: boolean;
    injuryAreas: string[];
    weightTrend: 'gaining' | 'losing' | 'stable' | 'unknown';
    calorieAdherence: number; // 0-1
  },
): string {
  const alerts: Array<{ level: 'warning' | 'info'; message: string }> = [];

  if (signals.avgRpe >= 9 && signals.weeklyVolumeTrend === 'increasing') {
    alerts.push({ level: 'warning', message: 'Высокий RPE + растущий объём = риск перетренированности. Запланируй разгрузку.' });
  }

  if (signals.hasInjury && signals.avgRpe >= 8) {
    alerts.push({ level: 'warning', message: `Тренировки с высокой нагрузкой при травме (${signals.injuryAreas.join(', ')}). Снизь интенсивность!` });
  }

  if (signals.weightTrend === 'losing' && signals.calorieAdherence < 0.7) {
    alerts.push({ level: 'info', message: 'Теряешь вес при недоборе калорий. Если цель не похудение — ешь больше.' });
  }

  if (signals.daysSinceLastWorkout >= 10) {
    alerts.push({ level: 'info', message: `${signals.daysSinceLastWorkout} дней без тренировки. Начинай возвращение постепенно — не прыгай сразу на тяжёлые веса.` });
  }

  if (alerts.length === 0) return '';

  return `\n\n## 🚨 АЛЕРТЫ ЗДОРОВЬЯ
${alerts.map(a => `${a.level === 'warning' ? '⚠️' : 'ℹ️'} ${a.message}`).join('\n')}
Упоминай алерты уместно — не пугай, но предупреждай.`;
}

// ─── Block 163: Smart Goal Setter ──────────────────────────────────────────
// Suggest SMART goals based on current progress

function suggestSmartGoals(
  currentStats: {
    totalWorkouts: number;
    currentStreak: number;
    avgVolume: number;
    strongestLift: { name: string; weight: number } | null;
    bodyWeight: number | null;
  },
  userGoal: string | null,
): string {
  const goals: string[] = [];

  // Short-term goals (1-2 weeks)
  if (currentStats.currentStreak < 7) {
    goals.push(`Краткосрочная: 7 дней подряд без пропусков (сейчас: ${currentStats.currentStreak})`);
  } else if (currentStats.currentStreak < 30) {
    goals.push(`Краткосрочная: 30 дней подряд (сейчас: ${currentStats.currentStreak})`);
  }

  // Strength goals
  if (currentStats.strongestLift) {
    const target = Math.round(currentStats.strongestLift.weight * 1.05 / 2.5) * 2.5;
    goals.push(`Сила: ${currentStats.strongestLift.name} → ${target} кг (сейчас: ${currentStats.strongestLift.weight} кг)`);
  }

  // Volume goals
  if (currentStats.avgVolume > 0) {
    const volTarget = Math.round(currentStats.avgVolume * 1.1);
    goals.push(`Объём: ${volTarget} кг за тренировку (сейчас: ~${Math.round(currentStats.avgVolume)} кг)`);
  }

  // Goal-specific
  if (userGoal === 'WEIGHT_LOSS' && currentStats.bodyWeight) {
    const target = Math.round(currentStats.bodyWeight - 2);
    goals.push(`Вес: ${target} кг через 4 недели (безопасный темп: -0.5 кг/нед)`);
  } else if (userGoal === 'MUSCLE_GAIN' && currentStats.bodyWeight) {
    const target = Math.round(currentStats.bodyWeight + 1);
    goals.push(`Масса: ${target} кг через 4 недели (чистый набор: +0.25 кг/нед)`);
  }

  if (goals.length === 0) return '';

  return `\n\n## 🎯 SMART-ЦЕЛИ
${goals.slice(0, 3).map(g => `- ${g}`).join('\n')}
Предложи цели если пользователь спрашивает о прогрессе или мотивации.`;
}

// ─── Block 164: Workout Rating Analyzer ────────────────────────────────────
// Analyze workout quality from multiple metrics

function rateWorkout(
  workout: {
    totalVolume: number | null;
    durationMinutes: number | null;
    exerciseCount: number;
    completedSets: number;
    totalSets: number;
    avgRpe: number;
  } | null,
): string {
  if (!workout || !workout.durationMinutes) return '';

  let score = 50; // base

  // Volume efficiency
  if (workout.totalVolume && workout.durationMinutes > 0) {
    const volPerMin = workout.totalVolume / workout.durationMinutes;
    if (volPerMin > 100) score += 15;
    else if (volPerMin > 50) score += 10;
    else if (volPerMin < 20) score -= 10;
  }

  // Completion rate
  const completionRate = workout.totalSets > 0 ? workout.completedSets / workout.totalSets : 1;
  if (completionRate >= 0.95) score += 15;
  else if (completionRate >= 0.8) score += 10;
  else if (completionRate < 0.6) score -= 15;

  // RPE sweet spot (6-8 is ideal for most)
  if (workout.avgRpe >= 6 && workout.avgRpe <= 8) score += 10;
  else if (workout.avgRpe > 9) score -= 5;

  // Duration (30-75 min optimal)
  if (workout.durationMinutes >= 30 && workout.durationMinutes <= 75) score += 10;
  else if (workout.durationMinutes > 120) score -= 10;

  // Exercise variety
  if (workout.exerciseCount >= 4 && workout.exerciseCount <= 8) score += 5;

  score = Math.max(0, Math.min(100, score));
  const rating = score >= 80 ? '⭐⭐⭐⭐⭐' : score >= 65 ? '⭐⭐⭐⭐' : score >= 50 ? '⭐⭐⭐' : score >= 35 ? '⭐⭐' : '⭐';

  return `\n\n## 📊 ОЦЕНКА ПОСЛЕДНЕЙ ТРЕНИРОВКИ: ${rating} (${score}/100)
${score >= 80 ? 'Отличная тренировка!' : score >= 50 ? 'Хорошая тренировка, есть куда расти.' : 'Можно лучше — проверь объём и завершённость подходов.'}
${completionRate < 0.8 ? `Завершено подходов: ${Math.round(completionRate * 100)}% — попробуй снизить веса.` : ''}`;
}

// ─── Block 165: Periodization Phase Advisor ────────────────────────────────
// Suggest which training phase to use next

function advisePeriodizationPhase(
  weeksSinceStart: number,
  currentPhase: string | null,
  recentPerformanceTrend: 'improving' | 'stagnating' | 'declining',
): string {
  if (weeksSinceStart < 4) return '';

  let nextPhase: string;
  let reason: string;

  if (recentPerformanceTrend === 'declining') {
    nextPhase = 'Разгрузка (1 неделя)';
    reason = 'Спад результатов — нужен отдых для суперкомпенсации.';
  } else if (recentPerformanceTrend === 'stagnating') {
    if (currentPhase === 'accumulation' || !currentPhase) {
      nextPhase = 'Интенсификация (3-4 недели)';
      reason = 'Стагнация в объёмной фазе — пора увеличивать интенсивность.';
    } else {
      nextPhase = 'Пиковая фаза (2 недели)';
      reason = 'Пора проверить новые максимумы.';
    }
  } else {
    if (weeksSinceStart % 12 < 4) {
      nextPhase = 'Накопление объёма (текущая)';
      reason = 'Прогресс идёт — продолжай в том же духе.';
    } else if (weeksSinceStart % 12 < 8) {
      nextPhase = 'Интенсификация (текущая)';
      reason = 'Время повышать веса и снижать объём.';
    } else {
      nextPhase = 'Пиковая фаза';
      reason = 'Финальная фаза цикла — выход на максимумы.';
    }
  }

  return `\n\n## 📅 ФАЗА ПЕРИОДИЗАЦИИ
Текущая рекомендация: ${nextPhase}
Причина: ${reason}
Предложи смену фазы если пользователь спрашивает о программе.`;
}

// ─── Block 166: Emotional Intelligence Layer ───────────────────────────────
// Detect emotional cues and respond appropriately

function buildEmotionalResponse(
  message: string,
  recentUserMessages: string[],
  currentStreak: number,
): string {
  const allText = [message, ...recentUserMessages.slice(0, 3)].join(' ').toLowerCase();

  const emotions: Record<string, { detected: boolean; response: string }> = {
    frustration: {
      detected: /не получается|не могу|задолбал|бесит|плохо|неудач|провал/i.test(allText),
      response: 'Пользователь фрустрирован. Будь эмпатичным, признай сложность, предложи конкретный маленький шаг вперёд.',
    },
    excitement: {
      detected: /ура|круто|рекорд|получилось|наконец-то|yes|!{2,}/i.test(allText),
      response: 'Пользователь в восторге! Раздели радость, похвали конкретное достижение, предложи следующую цель.',
    },
    anxiety: {
      detected: /боюсь|страшно|нервничаю|травм|опасно|не уверен/i.test(allText),
      response: 'Пользователь тревожится. Успокой, дай уверенность через факты и безопасные альтернативы.',
    },
    guilt: {
      detected: /пропустил|забил|не ходил|стыдно|плохой/i.test(allText),
      response: 'Пользователь чувствует вину за пропуск. НЕ вини. Нормализуй пропуски, предложи мягкое возвращение.',
    },
    pride: {
      detected: /горжусь|добился|смог|преодолел|сильнее/i.test(allText),
      response: 'Пользователь гордится собой. Усиль это чувство! Подчеркни путь и прогресс.',
    },
  };

  const detected = Object.entries(emotions)
    .filter(([, v]) => v.detected)
    .map(([, v]) => v.response);

  if (detected.length === 0) return '';

  return `\n\n## 💝 ЭМОЦИОНАЛЬНЫЙ КОНТЕКСТ
${detected.slice(0, 2).join('\n')}
Приоритет: эмоциональная поддержка > информация. Сначала прояви эмпатию, потом давай советы.`;
}

// ─── Block 167: Knowledge Gap Detector ─────────────────────────────────────
// Detect what the user doesn't know and educate proactively

function detectKnowledgeGaps(
  userLevel: string | null,
  totalWorkouts: number,
  hasUsedRPE: boolean,
  hasTrackedNutrition: boolean,
  hasSupersets: boolean,
): string {
  if (totalWorkouts > 100) return ''; // experienced user, don't lecture

  const gaps: string[] = [];

  if (!hasUsedRPE && totalWorkouts > 5) {
    gaps.push('RPE (шкала усилий): не используется. Объясни при случае — помогает управлять нагрузкой.');
  }

  if (!hasTrackedNutrition && totalWorkouts > 10) {
    gaps.push('Питание: не отслеживается. Упомяни что 70% результата зависит от еды.');
  }

  if (!hasSupersets && totalWorkouts > 15 && userLevel !== 'BEGINNER') {
    gaps.push('Суперсеты: не используются. Предложи для экономии времени и интенсивности.');
  }

  if (totalWorkouts > 20 && userLevel === 'BEGINNER') {
    gaps.push('20+ тренировок на уровне "новичок". Возможно пора обновить уровень в профиле.');
  }

  if (gaps.length === 0) return '';

  return `\n\n## 📚 ПРОБЕЛЫ В ЗНАНИЯХ
${gaps.slice(0, 2).map(g => `- ${g}`).join('\n')}
Обучай ненавязчиво — встраивай знания в ответы, не читай лекции.`;
}

// ─── Block 168: Context-Aware Greeting ─────────────────────────────────────
// Generate rich, personalized greetings

function buildContextGreeting(
  userName: string,
  currentHour: number,
  daysSinceLastWorkout: number,
  currentStreak: number,
  lastWorkoutName: string | null,
  todayCalories: number,
  targetCalories: number,
): string {
  const timeGreeting = currentHour < 6 ? 'Ранняя пташка!' :
                       currentHour < 12 ? 'Доброе утро' :
                       currentHour < 18 ? 'Добрый день' :
                       currentHour < 22 ? 'Добрый вечер' : 'Не спится?';

  const parts: string[] = [`${timeGreeting}, ${userName}!`];

  if (daysSinceLastWorkout === 0) {
    parts.push('Уже тренировался сегодня — красавец!');
  } else if (daysSinceLastWorkout === 1) {
    parts.push(`Вчера была ${lastWorkoutName || 'тренировка'}. Готов к новой?`);
  } else if (daysSinceLastWorkout >= 3) {
    parts.push(`Не тренировался ${daysSinceLastWorkout} дней. Самое время вернуться!`);
  }

  if (currentStreak >= 7) {
    parts.push(`Серия ${currentStreak} дней — огонь! 🔥`);
  }

  if (todayCalories > 0 && targetCalories > 0) {
    const pct = Math.round((todayCalories / targetCalories) * 100);
    if (pct < 50) parts.push(`Питание: пока только ${pct}% нормы.`);
  }

  return `\n\n## 👋 ПЕРСОНАЛИЗИРОВАННОЕ ПРИВЕТСТВИЕ
${parts.join(' ')}
Используй это как основу для приветственного сообщения.`;
}

// ─── Block 169: Anti-Broscience Filter ─────────────────────────────────────
// Detect and counter common fitness myths in user messages

function filterBroscience(message: string): string {
  const myths: Array<{ trigger: RegExp; correction: string }> = [
    { trigger: /углевод.*(вечер|ночь|после 6)/i, correction: 'Миф: "углеводы после 6 превращаются в жир". Факт: время приёма углеводов почти не влияет на набор жира — важен общий калорийный баланс.' },
    { trigger: /жиросжигающ.*(зон|пульс|кардио)/i, correction: 'Миф: "жиросжигающая зона пульса". Факт: высокоинтенсивное кардио сжигает больше калорий за меньшее время. Оба подхода работают.' },
    { trigger: /мышц.*(жир|перейд|превращ)/i, correction: 'Миф: "мышцы превращаются в жир". Факт: это разные ткани. Мышцы атрофируются отдельно, жир накапливается отдельно.' },
    { trigger: /есть.*каждые.*(2|3) часа/i, correction: 'Миф: "есть каждые 2-3 часа для разгона метаболизма". Факт: частота приёмов пищи не влияет на метаболизм. Важен общий дневной калораж.' },
    { trigger: /присед.*(колен|вред|опасн)/i, correction: 'Миф: "приседания вредят коленям". Факт: правильные приседания УКРЕПЛЯЮТ колени. Важна техника и прогрессия.' },
    { trigger: /белок.*бол[ьш].*(30|40|50) гр/i, correction: 'Миф: "организм усваивает только 30г белка за раз". Факт: организм усваивает весь белок, просто медленнее при больших порциях.' },
  ];

  const triggered = myths.filter(m => m.trigger.test(message));
  if (triggered.length === 0) return '';

  return `\n\n## 🔬 НАУЧНЫЙ ФАКТ-ЧЕК
${triggered.map(t => t.correction).join('\n\n')}
Мягко развей миф, опираясь на науку. Не высмеивай — многие так думают.`;
}

// ─── Block 170: Session Summary Generator ──────────────────────────────────
// At the end of a long conversation, summarize key takeaways

function shouldSummarizeSession(messageCount: number, intent: string): string {
  if (messageCount < 10) return '';

  if (messageCount % 10 === 0) {
    return `\n\n## 📝 РЕЗЮМЕ СЕССИИ
Длинный диалог (${messageCount} сообщений). При следующем удобном моменте предложи краткое резюме:
- Что обсудили
- Какие решения приняли
- Что делать дальше
Это поможет пользователю не потерять ключевые выводы.`;
  }

  return '';
}

// ─── Block 171: Strength-to-Weight Ratio Analyzer ─────────────────────────
// Calculate and contextualize strength-to-weight ratios

function analyzeStrengthToWeight(
  bodyWeight: number | null,
  lifts: Record<string, number>, // exercise name -> best weight
  gender: string | null,
): string {
  if (!bodyWeight || bodyWeight <= 0) return '';

  const ratios: string[] = [];
  const standards: Record<string, Record<string, number[]>> = {
    // [novice, intermediate, advanced, elite] multiples of bodyweight
    'жим лёжа': { male: [0.5, 1.0, 1.5, 2.0], female: [0.3, 0.6, 1.0, 1.3] },
    'присед': { male: [0.75, 1.25, 1.75, 2.5], female: [0.5, 0.8, 1.25, 1.75] },
    'становая тяга': { male: [1.0, 1.5, 2.25, 3.0], female: [0.75, 1.0, 1.75, 2.25] },
    'жим стоя': { male: [0.35, 0.65, 1.0, 1.35], female: [0.2, 0.4, 0.65, 0.85] },
  };

  const genderKey = gender?.toLowerCase() === 'female' ? 'female' : 'male';

  for (const [lift, weight] of Object.entries(lifts)) {
    const liftL = lift.toLowerCase();
    for (const [key, std] of Object.entries(standards)) {
      if (liftL.includes(key)) {
        const ratio = weight / bodyWeight;
        const levelStd = std[genderKey];
        const level = ratio < levelStd[0] ? 'ниже новичка' :
                      ratio < levelStd[1] ? 'новичок' :
                      ratio < levelStd[2] ? 'средний' :
                      ratio < levelStd[3] ? 'продвинутый' : 'элита';
        ratios.push(`${key}: ${weight}кг = ${ratio.toFixed(2)}× вес тела → уровень: **${level}**`);
        break;
      }
    }
  }

  if (ratios.length === 0) return '';

  return `\n\n## ⚖️ СИЛА ОТНОСИТЕЛЬНО ВЕСА ТЕЛА
${ratios.join('\n')}
Используй для мотивации и постановки целей.`;
}

// ─── Block 172: Training Volume Periodization ──────────────────────────────
// Smart volume recommendations for each week of a mesocycle

function getVolumeForWeek(
  weekNumber: number,
  mesocycleLength: number,
  baseVolume: number,
): string {
  if (baseVolume <= 0) return '';

  const weekInCycle = weekNumber % mesocycleLength;
  let volumeMultiplier: number;
  let weekType: string;

  if (mesocycleLength === 4) {
    const multipliers = [1.0, 1.1, 1.2, 0.6]; // 3 load + 1 deload
    volumeMultiplier = multipliers[weekInCycle] || 1.0;
    weekType = weekInCycle === 3 ? 'Разгрузка' : `Нагрузочная ${weekInCycle + 1}`;
  } else {
    const multipliers = [0.9, 1.0, 1.1, 1.2, 1.3, 0.6]; // 5 load + 1 deload
    volumeMultiplier = multipliers[Math.min(weekInCycle, multipliers.length - 1)] || 1.0;
    weekType = weekInCycle >= 5 ? 'Разгрузка' : `Нагрузочная ${weekInCycle + 1}`;
  }

  const targetVolume = Math.round(baseVolume * volumeMultiplier);

  return `\n\n## 📅 ОБЪЁМ НА ТЕКУЩУЮ НЕДЕЛЮ
Неделя ${weekNumber + 1} цикла (${weekType}): целевой объём ~${targetVolume} кг
${weekType.includes('Разгруз') ? 'Снизь интенсивность и объём — это запланировано!' : `${Math.round(volumeMultiplier * 100)}% от базового объёма.`}`;
}

// ─── Block 173: Nutrition Myth Buster ──────────────────────────────────────
// Counter common Russian nutrition myths specific to fitness

function bustNutritionMyths(message: string): string {
  const myths = [
    {
      triggers: /протеин.*(порош|коктейл|добавк)/i,
      fact: 'Протеиновые порошки — просто еда. Нет разницы между порошковым и пищевым белком (если нет проблем с ЖКТ). Используй для удобства, не как замену обычного питания.',
    },
    {
      triggers: /жир.*(замедл|плох|нельзя)/i,
      fact: 'Жиры необходимы! Без них не усваиваются витамины A/D/E/K и не производятся гормоны. Ешь жиры, но выбирай ненасыщенные: орехи, рыба, авокадо.',
    },
    {
      triggers: /соль.*(вред|нельзя|убирать)/i,
      fact: 'Для спортсменов соль важна! Теряешь натрий с потом. Иодированная соль в норме (3-5г/день) полезна. Избыток вреден, но полный отказ — тоже.',
    },
    {
      triggers: /гейнер.*(набор|масс)/i,
      fact: 'Гейнер работает только если ешь меньше нормы. Дешевле и эффективнее: рис + куриная грудка + банан дадут те же макросы.',
    },
    {
      triggers: /кардио.*(натощак|утро.*жир)/i,
      fact: 'Кардио натощак НЕ сжигает больше жира по итогу дня. Разница минимальна. Лучше поешь — тренировка будет продуктивнее.',
    },
  ];

  const triggered = myths.filter(m => m.triggers.test(message));
  if (triggered.length === 0) return '';

  return `\n\n## 🔬 ФАКТ О ПИТАНИИ
${triggered.map(t => t.fact).join('\n\n')}`;
}

// ─── Block 174: Russian-Specific Fitness Culture Context ───────────────────
// Localized advice for Russian gym culture

function buildRussianGymContext(
  message: string,
): string {
  const contexts: Array<{ trigger: RegExp; context: string }> = [
    {
      trigger: /рывок|толчок|тяга сумо|пауэрлифт/i,
      context: 'Российская школа пауэрлифтинга — одна из сильнейших в мире. ФПРС (федерация пауэрлифтинга) проводит соревнования по всей стране.',
    },
    {
      trigger: /соревнован|турнир|выступ/i,
      context: 'Для соревнований в России: ФПРС (пауэрлифтинг), ФБР (бодибилдинг), РФС (фитнес). Региональные старты есть в каждом городе-миллионнике.',
    },
    {
      trigger: /гречк|творог|кефир|тушенк/i,
      context: 'Российские продукты для спортсмена: гречка — медленные углеводы, творог — казеин перед сном, кефир — белок и пробиотики. Отличные, доступные продукты.',
    },
    {
      trigger: /аптек|аптечн/i,
      context: 'Из российских аптек: глюкозамин+хондроитин, магний B6, омега-3 (рыбий жир), витамин D3 — всё доступно и эффективно для спортсмена.',
    },
    {
      trigger: /магазин спортивн|спортмастер|декатлон/i,
      context: 'Магазины спортпита в России: Olimp, PureProtein, Bombbar — отечественные бренды хорошего качества. СпортМастер, Декатлон — для инвентаря.',
    },
  ];

  const applicable = contexts.filter(c => c.trigger.test(message));
  if (applicable.length === 0) return '';

  return `\n\n## 🇷🇺 РОССИЙСКИЙ КОНТЕКСТ
${applicable.slice(0, 2).map(c => c.context).join('\n')}`;
}

// ─── Block 175: Conversation Intent Refinement ─────────────────────────────
// More granular intent detection for better responses

function refineIntent(message: string, baseIntent: string): string {
  const refinements: Record<string, RegExp> = {
    'asking_for_program': /создай|составь|напиши программ|сделай програм|нужна программ/i,
    'reporting_pain': /болит|боль|тянет|ноет|дискомф|травм/i,
    'asking_technique': /как (делать|выполнять)|техника|правильно ли|покажи как/i,
    'seeking_motivation': /не хочу|лень|мотив|зачем|смысл|устал от/i,
    'reporting_progress': /похудел|набрал|стал сильнее|прогресс|рекорд|вес вырос/i,
    'asking_nutrition': /что (есть|съесть|кушать)|рацион|диета|калории|белок/i,
    'asking_schedule': /когда тренир|расписание|план на неделю|сколько раз/i,
    'seeking_explanation': /почему|зачем|как работает|объясни|что такое/i,
  };

  const matched = Object.entries(refinements).filter(([, re]) => re.test(message)).map(([name]) => name);

  if (matched.length === 0) return '';

  return `\n\n## 🎯 УТОЧНЁННЫЙ ИНТЕНТ
Базовый: ${baseIntent}
Уточнённый: ${matched.join(', ')}
Адаптируй ответ под конкретный под-тип запроса.`;
}

// ─── Block 176: Adaptive Difficulty Ramp ──────────────────────────────────
// Auto-adjust program difficulty based on completion patterns

function adaptDifficultyRamp(
  recentWorkouts: Array<{
    exercises: Array<{
      sets: Array<{ completed: boolean; rpe: number | null; weight: number | null; reps: number | null }>;
    }>;
    durationMinutes: number | null;
  }>,
): string {
  if (recentWorkouts.length < 3) return '';

  // Avg completion rate per workout
  const rates = recentWorkouts.slice(0, 5).map(w => {
    const total = w.exercises.reduce((s, e) => s + e.sets.length, 0);
    const completed = w.exercises.reduce((s, e) => s + e.sets.filter(st => st.completed).length, 0);
    return total > 0 ? completed / total : 1;
  });

  const avgRate = rates.reduce((a, b) => a + b, 0) / rates.length;

  if (avgRate > 0.95) {
    return `\n\n## 📈 АДАПТАЦИЯ СЛОЖНОСТИ
Высокий % завершения подходов (${Math.round(avgRate * 100)}%). Программа слишком лёгкая.
Рекомендация: увеличь рабочие веса на 5% или добавь 1 подход к каждому упражнению.`;
  }

  if (avgRate < 0.7) {
    return `\n\n## 📉 АДАПТАЦИЯ СЛОЖНОСТИ
Низкий % завершения подходов (${Math.round(avgRate * 100)}%). Программа слишком тяжёлая.
Рекомендация: снизь веса на 10% или убери 1 подход. Лучше тренироваться стабильно.`;
  }

  return '';
}

// ─── Block 177: Exercise Biomechanics Insights ─────────────────────────────
// Biomechanics tips for common exercises

function buildBiomechanicsInsight(exerciseName: string): string {
  const biomechanics: Record<string, string> = {
    'жим лёжа': 'Лопатки сведены и прижаты к скамье → стабильная база. Ширина хвата: немного шире плеч. Локти 45° к телу для плечей.',
    'присед': 'Колени над носками, но не "вовнутрь". Глубина: бёдра параллельно полу минимум. Нейтральная спина — не поясничный лордоз.',
    'становая тяга': 'Гриф над шнурками, прижат к голеням. Плечи над грифом. Бёдра назад, не вниз. Включай ягодицы в финале.',
    'подтягивания': 'Лопатки вниз первыми, потом локти. Полное разгибание внизу. Не раскачивайся — это читтинг.',
    'тяга штанги': 'Спина параллельна полу или чуть выше. Тяни к поясу, не к груди. Лопатки сводятся в конце.',
    'жим стоя': 'Гриф у ключиц, корпус вертикально. Ягодицы и кор напряжены. Голова отклоняется назад при проходе через лицо.',
    'румынская тяга': 'Бёдра назад, небольшой изгиб коленей. Гриф скользит вдоль ног. Чувствуешь растяжение задней поверхности — правильно.',
  };

  const nameL = exerciseName.toLowerCase();
  for (const [key, insight] of Object.entries(biomechanics)) {
    if (nameL.includes(key)) {
      return insight;
    }
  }
  return '';
}

function buildBiomechanicsContext(exercises: string[]): string {
  const insights: string[] = [];
  for (const ex of exercises.slice(0, 3)) {
    const insight = buildBiomechanicsInsight(ex);
    if (insight) insights.push(`**${ex}**: ${insight}`);
  }

  if (insights.length === 0) return '';

  return `\n\n## 🦴 БИОМЕХАНИКА
${insights.join('\n\n')}
Используй при объяснении техники.`;
}

// ─── Block 178: Pre-Workout Checklist ──────────────────────────────────────
// Generate a pre-workout checklist based on context

function buildPreWorkoutChecklist(
  lastMealHoursAgo: number | null,
  userHydrated: boolean,
  warmupDone: boolean,
  focusExercise: string | null,
): string {
  const checklist: Array<{ done: boolean; item: string }> = [
    { done: lastMealHoursAgo !== null && lastMealHoursAgo >= 1 && lastMealHoursAgo <= 3, item: 'Поел за 1-3 часа до тренировки' },
    { done: userHydrated, item: 'Выпил 400-500 мл воды за час до тренировки' },
    { done: warmupDone, item: '5 мин кардио + суставная разминка' },
    { done: false, item: 'Знаешь план тренировки (упражнения, подходы, веса)' },
    { done: false, item: 'Телефон в режиме "не беспокоить"' },
  ];

  if (focusExercise) {
    checklist.push({ done: false, item: `Разминочные подходы перед ${focusExercise}` });
  }

  const pending = checklist.filter(c => !c.done);
  if (pending.length === 0) return '';

  return `\n\n## ✅ ЧЕК-ЛИСТ ПЕРЕД ТРЕНИРОВКОЙ
${checklist.map(c => `${c.done ? '✅' : '☐'} ${c.item}`).join('\n')}
Предложи это если пользователь говорит что собирается тренироваться.`;
}

// ─── Block 179: Long-Term Progress Narrative ───────────────────────────────
// Tell user's fitness journey as a narrative

function buildProgressNarrative(
  totalWorkouts: number,
  firstWorkoutDaysAgo: number,
  currentStreak: number,
  totalVolumeTons: number,
  personalRecords: number,
): string {
  if (totalWorkouts < 5) return '';

  const parts: string[] = [];

  // Journey duration
  if (firstWorkoutDaysAgo >= 30) {
    parts.push(`${Math.round(firstWorkoutDaysAgo / 30)} месяц(ев) в зале`);
  }

  // Volume moved
  if (totalVolumeTons >= 1) {
    parts.push(`${totalVolumeTons.toFixed(1)} тонн поднято за всё время`);
  }

  // Workout count
  if (totalWorkouts >= 50) {
    parts.push(`${totalWorkouts} тренировок в истории`);
  }

  // Consistency
  if (currentStreak >= 14) {
    parts.push(`${currentStreak} дней без пропуска сейчас`);
  }

  if (personalRecords > 0) {
    parts.push(`${personalRecords} личных рекордов`);
  }

  if (parts.length < 2) return '';

  return `\n\n## 📖 ИСТОРИЯ ПРОГРЕССА
${parts.map(p => `🏆 ${p}`).join('\n')}
Используй для мотивации — покажи пользователю насколько далеко он продвинулся.`;
}

// ─── Block 180: Contextual Action Suggestions ─────────────────────────────
// Suggest specific next actions in the app based on context

function suggestNextActions(
  intent: string,
  hasActiveProgram: boolean,
  lastWorkoutDaysAgo: number,
  nutritionTracked: boolean,
): string {
  const actions: string[] = [];

  if (intent === 'greeting' || intent === 'general') {
    if (lastWorkoutDaysAgo >= 2) {
      actions.push('🏋️ Начать тренировку: открой вкладку «Тренировки»');
    }
    if (!nutritionTracked) {
      actions.push('🥗 Записать питание: вкладка «Питание» → добавить приём пищи');
    }
    if (!hasActiveProgram) {
      actions.push('📋 Создать программу: AI Coach поможет составить план');
    }
  }

  if (intent === 'workout') {
    actions.push('▶️ Начать тренировку прямо сейчас — запусти таймер');
    if (hasActiveProgram) actions.push('📋 Следуй активной программе');
  }

  if (intent === 'nutrition') {
    actions.push('📸 Сфотографировать еду для автоматического подсчёта КБЖУ');
    actions.push('✏️ Ввести вручную: поиск по базе продуктов');
  }

  if (actions.length === 0) return '';

  return `\n\n## 👆 СЛЕДУЮЩИЙ ШАГ В ПРИЛОЖЕНИИ
${actions.slice(0, 2).map(a => `- ${a}`).join('\n')}
Предложи конкретные действия в приложении если уместно.`;
}

// ─── Block 181: Macro Split Advisor ───────────────────────────────────────────
// Recommend protein/carb/fat split based on goal and training intensity

function getMacroSplitAdvice(
  goal: string | null,
  bodyWeightKg: number | null,
  trainingDaysPerWeek: number,
): string {
  if (!bodyWeightKg) return '';

  const protein = Math.round(bodyWeightKg * (goal === 'weight_loss' ? 2.2 : goal === 'muscle_gain' ? 2.0 : 1.8));
  let carbPct: number;
  let fatPct: number;

  if (goal === 'weight_loss') {
    carbPct = trainingDaysPerWeek >= 4 ? 35 : 30;
    fatPct = 30;
  } else if (goal === 'muscle_gain') {
    carbPct = 45;
    fatPct = 25;
  } else {
    carbPct = 40;
    fatPct = 30;
  }

  const proteinPct = 100 - carbPct - fatPct;
  const cals = protein * 4 + Math.round(bodyWeightKg * 35);
  const carbs = Math.round((cals * carbPct) / 100 / 4);
  const fats = Math.round((cals * fatPct) / 100 / 9);

  return `\n\n## 🥩 РЕКОМЕНДУЕМОЕ СООТНОШЕНИЕ МАКРОСОВ
Цель: ${goal === 'weight_loss' ? 'похудение' : goal === 'muscle_gain' ? 'набор массы' : 'поддержание формы'}
Белок: ~${protein}г/день (${proteinPct}% калорий)
Углеводы: ~${carbs}г/день (${carbPct}% калорий)
Жиры: ~${fats}г/день (${fatPct}% калорий)
Используй если пользователь спрашивает про питание или похудение.`;
}

